<?php
require_once __DIR__.'/_auth.php';require_once __DIR__.'/_layout.php';require_once __DIR__.'/_folha_pagamentos.php';
$db=db();$error='';$id=(int)($_GET['id']??$_POST['funcionario_id']??0);$mes=folhaMes($_GET['mes']??$_POST['mes']??'');
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrfVerify();$action=$_POST['action']??'';
 try{
  if(in_array($action,['salvar','excluir'],true)){
   $db->beginTransaction();$old=null;
   if($id){$s=$db->prepare('SELECT * FROM centro_funcionarios WHERE id=? FOR UPDATE');$s->execute([$id]);$old=$s->fetch();if(!$old)throw new InvalidArgumentException('Funcionário não encontrado.');}
   if($action==='excluir'){
    if(!$old||!isset($_POST['confirmar_exclusao'])||trim($_POST['confirmar_nome']??'')!==$old['nome'])throw new InvalidArgumentException('Para excluir, marque a confirmação e digite o nome completo do funcionário.');
    $s=$db->prepare('SELECT * FROM centro_folha_pagamentos WHERE funcionario_id=? FOR UPDATE');$s->execute([$id]);
    foreach($s->fetchAll() as $payment)auditLog('delete','centro_folha_pagamentos',(int)$payment['id'],$payment);
    auditLog('delete','centro_funcionarios',$id,$old);
    $db->prepare('DELETE FROM centro_folha_pagamentos WHERE funcionario_id=?')->execute([$id]);$db->prepare('DELETE FROM centro_funcionarios WHERE id=?')->execute([$id]);$db->commit();redirect('/admin/financeiro_funcionarios.php?deleted=1&mes='.urlencode($mes));
   }
   $values=[];
   foreach(['nome'=>150,'cpf'=>20,'telefone'=>30,'pix_chave'=>150,'banco_info'=>150] as $key=>$limit){$value=trim(is_string($_POST[$key]??null)?$_POST[$key]:'');if(!preg_match('/^.{0,'.$limit.'}$/us',$value)||($key==='nome'&&$value===''))throw new InvalidArgumentException('Confira o campo '.$key.'.');$values[]=$value;}
   $s=$db->prepare('SELECT id FROM centro_funcionarios WHERE nome=? AND id<>?');$s->execute([$values[0],$id]);if($s->fetch())throw new InvalidArgumentException('Já existe um funcionário com esse nome.');
   $values[]=isset($_POST['ativo'])?1:0;
   if($id)$db->prepare('UPDATE centro_funcionarios SET nome=?,cpf=?,telefone=?,pix_chave=?,banco_info=?,ativo=? WHERE id=?')->execute(array_merge($values,[$id]));
   else{$db->prepare('INSERT INTO centro_funcionarios(nome,cpf,telefone,pix_chave,banco_info,ativo) VALUES(?,?,?,?,?,?)')->execute($values);$id=(int)$db->lastInsertId();}
   auditLog($old?'update':'create','centro_funcionarios',$id,['antes'=>$old,'depois'=>array_combine(['nome','cpf','telefone','pix_chave','banco_info','ativo'],$values)]);$db->commit();
   redirect('/admin/financeiro_funcionarios.php?id='.$id.'&mes='.urlencode($mes).'&saved=1');
  }
  if($action==='pagamento'){
   $db->beginTransaction();$s=$db->prepare('SELECT * FROM centro_folha_pagamentos WHERE id=? AND funcionario_id=? FOR UPDATE');$s->execute([(int)($_POST['pagamento_id']??0),$id]);$payment=$s->fetch();if(!$payment)throw new InvalidArgumentException('Pagamento não encontrado.');
   $previsto=folhaCentavos($payment['valor'])+folhaCentavos($payment['vale_transporte']);$mode=$_POST['modo']??'';
   if($mode==='a_confirmar'){$status='a_confirmar';$paid=null;$date=null;}
   elseif($mode==='pendente'){$status='pendente';$paid='0.00';$date=null;}
   elseif($mode==='registrar'){$cents=folhaCentavos($_POST['valor_pago']??'');if($cents<=0||$cents>$previsto)throw new InvalidArgumentException('Valor pago deve ser maior que zero e não pode ultrapassar o previsto. Ajuste o lançamento da folha se necessário.');$paid=folhaDecimal($cents);$status=$cents===$previsto?'pago':'parcial';$date=folhaData($_POST['data_pagamento']??'');}
   else throw new InvalidArgumentException('Ação de pagamento inválida.');
   $db->prepare('UPDATE centro_folha_pagamentos SET situacao_pagamento=?,valor_pago=?,data_pagamento=? WHERE id=? AND funcionario_id=?')->execute([$status,$paid,$date,$payment['id'],$id]);
   auditLog('update','centro_folha_pagamentos',(int)$payment['id'],['antes'=>$payment,'situacao_pagamento'=>$status,'valor_pago'=>$paid,'data_pagamento'=>$date]);$db->commit();
   redirect('/admin/financeiro_funcionarios.php?id='.$id.'&mes='.urlencode($mes).'&saved=1');
  }
  throw new InvalidArgumentException('Ação inválida.');
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e instanceof InvalidArgumentException?$e->getMessage():'Não foi possível salvar. Confira os dados e tente novamente.';error_log('[Axion folha] '.$e->getMessage());}
}
$person=null;$payments=[];
if($id){$s=$db->prepare('SELECT * FROM centro_funcionarios WHERE id=?');$s->execute([$id]);$person=$s->fetch();if(!$person){http_response_code(404);exit('Funcionário não encontrado.');}
 $s=$db->prepare("SELECT pg.*,p.data_periodo,p.tipo,COALESCE(p.competencia,DATE_FORMAT(p.data_periodo,'%Y-%m')) AS competencia FROM centro_folha_pagamentos pg JOIN centro_folha_periodos p ON p.id=pg.periodo_id WHERE pg.funcionario_id=? AND COALESCE(p.competencia,DATE_FORMAT(p.data_periodo,'%Y-%m'))=? ORDER BY p.data_periodo,pg.id");$s->execute([$id,$mes]);$payments=$s->fetchAll();}
$s=$db->prepare("SELECT f.*,COALESCE(m.previsto,0) previsto,COALESCE(m.pago,0) pago,COALESCE(m.qtd,0) qtd,COALESCE(m.desconhecidos,0) desconhecidos FROM centro_funcionarios f LEFT JOIN (SELECT pg.funcionario_id,SUM(pg.valor+pg.vale_transporte) previsto,SUM(COALESCE(pg.valor_pago,0)) pago,COUNT(*) qtd,SUM(pg.situacao_pagamento='a_confirmar') desconhecidos FROM centro_folha_pagamentos pg JOIN centro_folha_periodos p ON p.id=pg.periodo_id WHERE COALESCE(p.competencia,DATE_FORMAT(p.data_periodo,'%Y-%m'))=? GROUP BY pg.funcionario_id) m ON m.funcionario_id=f.id ORDER BY f.ativo DESC,f.nome");$s->execute([$mes]);$people=$s->fetchAll();
$summary=['previsto'=>0,'pago'=>0,'desconhecidos'=>0,'qtd'=>0];foreach($payments as $p){$summary['previsto']+=folhaCentavos($p['valor'])+folhaCentavos($p['vale_transporte']);$summary['pago']+=folhaCentavos($p['valor_pago']??'0');$summary['desconhecidos']+=$p['situacao_pagamento']==='a_confirmar';$summary['qtd']++;}
$search=is_string($_GET['busca']??null)?trim($_GET['busca']):'';
$statusFilter=is_string($_GET['situacao']??null)?$_GET['situacao']:'';
$activeFilter=in_array($_GET['ativo']??'',['1','0'],true)?$_GET['ativo']:'';
$people=array_filter($people,function($f)use($search,$statusFilter,$activeFilter){
 $status=folhaSituacao(folhaCentavos($f['previsto']),folhaCentavos($f['pago']),(int)$f['desconhecidos'],(int)$f['qtd']);
 return ($search===''||stripos($f['nome'],$search)!==false)&&(!isset(FOLHA_SITUACOES[$statusFilter])||$status===$statusFilter)&&($activeFilter===''||(int)$f['ativo']===(int)$activeFilter);
});
layout_start('Funcionários e pagamentos','financeiro');$finTab='funcionarios';require __DIR__.'/_financeiro_nav.php';
?>
<link rel="stylesheet" href="/css/funcionarios.css?v=20261022">
<?php if($error): ?><div class="alert alert-error"><?= e($error) ?></div><?php endif ?>
<?php if(isset($_GET['saved'])): ?><div class="alert alert-success">Alteração salva e registrada na auditoria.</div><?php endif ?>
<?php if(isset($_GET['deleted'])): ?><div class="alert alert-success">Funcionário excluído. O histórico da exclusão foi preservado na auditoria.</div><?php endif ?>
<div class="card staff-heading"><div><h2><?= e($person?$person['nome']:'Funcionários') ?></h2><p>Cadastro e acompanhamento por competência, com pagamentos confirmados separadamente.</p></div><form method="GET" class="staff-month"><?php if($id): ?><input type="hidden" name="id" value="<?= $id ?>"><?php endif ?><label>Competência<input type="month" name="mes" value="<?= e($mes) ?>" required></label><button class="btn btn-secondary">Consultar</button></form></div>
<?php if($person): ?>
<a class="btn btn-ghost btn-sm" href="?mes=<?= e($mes) ?>">← Todos os funcionários</a>
<div class="kpi-grid" style="margin-top:16px"><div class="kpi"><div class="kpi-label">Previsto no mês</div><div class="kpi-val mono"><?= e(brl($summary['previsto']/100)) ?></div></div><div class="kpi"><div class="kpi-label">Pago confirmado</div><div class="kpi-val g mono"><?= e(brl($summary['pago']/100)) ?></div></div><div class="kpi"><div class="kpi-label">Saldo a conferir / pagar</div><div class="kpi-val mono"><?= e(brl(max(0,$summary['previsto']-$summary['pago'])/100)) ?></div></div><div class="kpi"><div class="kpi-label">Situação da competência</div><div class="staff-big-status"><?= e(FOLHA_SITUACOES[folhaSituacao(...array_values($summary))]) ?></div></div></div>
<?php endif ?>
<details class="card" <?= (!$person&&isset($_GET['novo']))?'open':'' ?>><summary class="staff-summary"><?= $person?'Editar cadastro':'Cadastrar funcionário' ?></summary><form method="POST" class="frow staff-form"><?= csrfField() ?><input type="hidden" name="action" value="salvar"><input type="hidden" name="funcionario_id" value="<?= $id ?>"><input type="hidden" name="mes" value="<?= e($mes) ?>"><?php foreach(['nome'=>['Nome completo',150],'cpf'=>['CPF',20],'telefone'=>['Telefone',30],'pix_chave'=>['Chave PIX',150],'banco_info'=>['Banco / agência / conta',150]] as $key=>[$label,$limit]): ?><div class="fg"><label><?= $label ?></label><input name="<?= $key ?>" maxlength="<?= $limit ?>" value="<?= e($person[$key]??'') ?>" <?= $key==='nome'?'required':'' ?>></div><?php endforeach ?><label class="staff-check"><input type="checkbox" name="ativo" <?= !$person||$person['ativo']?'checked':'' ?>> Funcionário ativo</label><div class="staff-actions"><button class="btn btn-primary">Salvar cadastro</button></div></form></details>
<?php if(!$person): ?>
<form method="GET" class="card frow staff-form staff-filters"><input type="hidden" name="mes" value="<?= e($mes) ?>"><div class="fg"><label>Buscar funcionário</label><input type="search" name="busca" value="<?= e($search) ?>" placeholder="Nome do funcionário"></div><div class="fg"><label>Pagamento no mês</label><select name="situacao"><option value="">Todas as situações</option><?php foreach(FOLHA_SITUACOES as $value=>$label): ?><option value="<?= $value ?>" <?= $statusFilter===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select></div><div class="fg"><label>Cadastro</label><select name="ativo"><option value="">Ativos e inativos</option><option value="1" <?= $activeFilter==='1'?'selected':'' ?>>Ativos</option><option value="0" <?= $activeFilter==='0'?'selected':'' ?>>Inativos</option></select></div><div class="staff-actions"><button class="btn btn-secondary">Filtrar</button><a class="btn btn-ghost" href="?mes=<?= e($mes) ?>">Limpar filtros</a></div></form>
<div class="card"><div class="staff-actions"><a class="btn btn-primary" href="?novo=1&mes=<?= e($mes) ?>">+ Novo funcionário</a><a class="btn btn-ghost" href="/admin/financeiro_folha.php">Lançar folha / períodos</a><a class="btn btn-ghost" href="/admin/financeiro_pendencias.php">Conferir dados importados</a></div><p class="text-muted" style="margin:14px 0">“Pago” exige confirmação de todos os lançamentos do mês. Ausência de lançamento não significa quitação. Cabeçalhos de fechamento próximos ao início do mês usam a competência anterior; confira os períodos importados.</p><div class="staff-scroll"><table><thead><tr><th>Funcionário</th><th>PIX</th><th>Previsto</th><th>Pago confirmado</th><th>Situação no mês</th><th></th></tr></thead><tbody><?php foreach($people as $f):$status=folhaSituacao(folhaCentavos($f['previsto']),folhaCentavos($f['pago']),(int)$f['desconhecidos'],(int)$f['qtd']); ?><tr><td><strong><?= e($f['nome']) ?></strong><div class="td-sub"><?= $f['ativo']?'Ativo':'Inativo' ?></div></td><td class="staff-pix"><?= e($f['pix_chave']?:'Não informado') ?></td><td class="mono"><?= e(brl($f['previsto'])) ?></td><td class="mono"><?= e(brl($f['pago'])) ?></td><td><span class="staff-status staff-<?= $status ?>"><?= e(FOLHA_SITUACOES[$status]) ?></span></td><td><a class="btn btn-secondary btn-sm" href="?id=<?= (int)$f['id'] ?>&mes=<?= e($mes) ?>">Abrir ficha</a></td></tr><?php endforeach ?></tbody></table></div></div>
<?php else: ?>
<div class="card"><div class="card-title">Pagamentos da competência <?= e($mes) ?></div><p class="text-muted">Confirmar um pagamento aqui atualiza a folha; não gera outra saída no fluxo de caixa. Informe o valor pago acumulado deste lançamento. Para corrigir o previsto, use a edição na folha.</p><div class="staff-scroll"><table><thead><tr><th>Período</th><th>Previsto + transporte</th><th>Pago</th><th>Situação</th><th>Ação</th></tr></thead><tbody><?php foreach($payments as $p):$expected=folhaCentavos($p['valor'])+folhaCentavos($p['vale_transporte']); ?><tr><td><?= e(date('d/m/Y',strtotime($p['data_periodo']))) ?><div class="td-sub"><?= e($p['tipo']) ?></div><div class="td-sub"><?= e($p['observacao']) ?></div></td><td><?= e(brl($expected/100)) ?></td><td><?= $p['valor_pago']===null?'Não confirmado':e(brl($p['valor_pago'])) ?><div class="td-sub"><?= e($p['data_pagamento']??'') ?></div></td><td><span class="staff-status staff-<?= e($p['situacao_pagamento']) ?>"><?= e(FOLHA_SITUACOES[$p['situacao_pagamento']]??'A confirmar') ?></span></td><td><details><summary class="staff-summary">Registrar / corrigir</summary><form method="POST" class="staff-pay-form"><?= csrfField() ?><input type="hidden" name="action" value="pagamento"><input type="hidden" name="funcionario_id" value="<?= $id ?>"><input type="hidden" name="pagamento_id" value="<?= (int)$p['id'] ?>"><input type="hidden" name="mes" value="<?= e($mes) ?>"><div class="fg"><label>Operação</label><select name="modo"><option value="registrar">Registrar valor pago</option><option value="pendente">Marcar pendente (R$ 0 pago)</option><option value="a_confirmar">Voltar para a confirmar</option></select></div><div class="fg"><label>Valor pago acumulado (R$)</label><input type="number" name="valor_pago" step="0.01" min="0" max="<?= folhaDecimal($expected) ?>" value="<?= e($p['valor_pago']??folhaDecimal($expected)) ?>"></div><div class="fg"><label>Data do pagamento</label><input type="date" name="data_pagamento" value="<?= e($p['data_pagamento']??'') ?>"></div><button class="btn btn-primary btn-sm">Salvar confirmação</button></form><a class="btn btn-ghost btn-sm" href="/admin/financeiro_folha.php?periodo_id=<?= (int)$p['periodo_id'] ?>">Editar lançamento na folha</a></details></td></tr><?php endforeach ?></tbody></table></div><?php if(!$payments): ?><p style="margin-top:16px">Não há lançamentos nesta competência. Cadastre o período e o pagamento na folha para acompanhar a quitação.</p><?php endif ?></div>
<details class="card"><summary class="staff-summary">Excluir funcionário e seus lançamentos</summary><p style="margin:16px 0">A exclusão remove este cadastro e seus pagamentos da folha. Os dados excluídos e a autoria ficam registrados na auditoria. Para preservar o cadastro no dia a dia, prefira desativá-lo em Editar cadastro.</p><form method="POST" class="staff-form"><?= csrfField() ?><input type="hidden" name="action" value="excluir"><input type="hidden" name="funcionario_id" value="<?= $id ?>"><div class="fg"><label>Digite o nome completo para confirmar</label><input name="confirmar_nome" required autocomplete="off"></div><label class="staff-check"><input type="checkbox" name="confirmar_exclusao" required> Confirmo a exclusão do funcionário e dos pagamentos vinculados.</label><button class="btn btn-danger">Excluir funcionário</button></form></details>
<?php endif;layout_end(); ?>
